contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        uint256 cBalBeforeDeposit = address(c).balance;
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint256 cBalAfterDeposit = address(c).balance;

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalAfterWithdraw = address(c).balance;

        bool expectedRevert = withdrawAmount > cBalAfterDeposit - cBalBeforeDeposit;
        assert(reverted == expectedRevert && (reverted || cBalAfterWithdraw == cBalAfterDeposit - withdrawAmount));
    }

    receive() external payable {}
}

